    "statement": "IF tool_name = \"approve_mortgage\" AND skip_marriage_verification = False AND marriage_status_verified ≠ True THEN policy returns (False, \"Marriage status not verified and skip_marriage_verification not set.\")"
  },
  {
    "statement": "IF tool_name = \"approve_mortgage\" AND ltv_dti_calculated ≠ True THEN policy returns (False, \"LTV/DTI not calculated before approving mortgage.\")"
